 if(!request.headers.get('content-type')?.startsWith('application/json'))return json({error:'JSON required'},415);
 const ip=request.headers.get('CF-Connecting-IP')||'unknown',minute=Math.floor(Date.now()/60000),key=ip+':'+minute,count=rates.get(key)||0;if(count>=30)return json({error:'Too many edits. Try again in a minute.'},429);rates.set(key,count+1);if(rates.size>5000)rates.clear();
 let data;try{const reader=request.body?.getReader();let body='';if(reader){const decoder=new TextDecoder();for(;;){const part=await reader.read();if(part.done)break;body+=decoder.decode(part.value,{stream:true});if(body.length>2048){await reader.cancel();return json({error:'Task is too large.'},413);}}}if(body.length>2048)return json({error:'Task is too large.'},413);data=JSON.parse(body);}catch{return json({error:'Invalid JSON'},400);}
 if(typeof data.text!=='string'||!data.text.trim()||data.text.trim().length>500)return json({error:'Task text must be 1–500 characters.'},400);
 const text=data.text.trim(),now=new Date().toISOString();
 if(path==='/api/tasks'){const id=crypto.randomUUID();const result=await env.DB.prepare('INSERT INTO tasks(id,text,done,revision,created_at,updated_at) SELECT ?,?,0,1,?,? WHERE (SELECT COUNT(*) FROM tasks)<200').bind(id,text,now,now).run();if(!result.meta.changes)return json({error:'Task limit reached (200). Edit existing tasks.'},409);return json({id},201);}
 if(typeof data.done!=='boolean'||!Number.isInteger(data.revision)||data.revision<1)return json({error:'Invalid task update'},400);
 if(data.delete===true){const result=await env.DB.prepare('DELETE FROM tasks WHERE id=? AND revision=?').bind(path.split('/').pop(),data.revision).run();return result.meta.changes?json({ok:true}):json({error:'Task changed or was already deleted. Refresh and retry.'},409);}
